const fs = require('fs');
const ts = require('./node_modules/typescript');
const file = 'src/vs/workbench/contrib/sources/test/browser/conversationDiffReviewPane.test.ts';
const source = ts.createSourceFile(file, fs.readFileSync(file, 'utf8'), ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
const diagnostics = source.parseDiagnostics.map(diagnostic => ({ code: diagnostic.code, start: diagnostic.start, message: ts.flattenDiagnosticMessageText(diagnostic.messageText, '\n') }));
process.stdout.write(JSON.stringify({ file, createSourceFileCalls: 1, diagnostics }) + '\n');
if (diagnostics.length) { process.exitCode = 1; }
